INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('en-US', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'Genes to Mems Transition', 'Artificial intelligence envisions the boundary between biological and digital information carriers');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('uk-UA', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'Перехід від генів до мемів', 'Штучний інтелект уявляє межу між біологічними та цифровими носіями інформації.');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('de-DE', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'Übergang von Genen zu Mems', 'Künstliche Intelligenz entwirft die Grenze zwischen biologischen und digitalen Informationsträgern.');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('hi-IN', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'जीन्स से मेम्स का संक्रमण', 'कृत्रिम बुद्धिमत्ता जैविक और डिजिटल सूचना वाहकों के बीच की सीमा को देखती है।');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('ja-JP', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', '遺伝子からメムスへの移行', '人工知能は、生物情報とデジタル情報のキャリア間の境界を想像します。');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('ru-RU', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'Переход от генов к мемам', 'Искусственный интеллект предвидит границы между биологическими и цифровыми носителями информации');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('fr-FR', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'Transition des gènes aux mems', 'L''intelligence artificielle envisage la frontière entre les vecteurs d''information biologiques et numériques.');
INSERT INTO "media_locales" ("_locale", "_parent_id", "alt", "caption") VALUES ('es-ES', '11111111-67f9-b2c0-7fbd-e3cb7aa31947', 'Transición de Genes a Mems', 'La inteligencia artificial vislumbra el límite entre los portadores de información biológicos y digitales.');
