INSERT INTO "media_locales" ("_locale", "_parent_id", "alt") VALUES ('uk-UA', '11111111-6858-3709-75c8-056d98c1b5c3', 'Діаграма під назвою "Як я раптом створив 6-крокову реплікацію ланцюга для особистих нотаток". Праворуч показано шість пронумерованих кроків зі стрілками, що з''єднують іконки: чат-бульбашка, додаток для нотаток, логотип GitHub і символ завантаження в хмару. Ліворуч назва відображається на темному фоні.');
