INSERT INTO "media_locales" ("_locale", "_parent_id", "alt") VALUES ('hi-IN', '11111111-6858-3709-75c8-056d98c1b5c3', 'फ्लोचार्ट का शीर्षक ''कैसे मैंने अचानक से व्यक्तिगत नोट्स के लिए 6-स्टेप चेन प्रतिकृति बनाई''। दाईं ओर, छह क्रमांकित चरण दिखाए गए हैं जिनमें आइकनों को जोड़ते हुए तीर दिखाई दे रहे हैं: एक चैट बबल, नोट ऐप, GitHub लोगो और क्लाउड अपलोड प्रतीक। बाईं ओर, शीर्षक एक गहरे पृष्ठभूमि पर प्रदर्शित है।');
